  /**
   * createImpl
   */
  @Override
  public Long createObjectSku(ObjectSkuCreateRequest request) {
    ObjectSkuCreator creator = ObjectSkuMapper.INSTANCE.request2Dto(request);
    Optional<ObjectSku> objectSku = EntityOperations.doCreate(objectSkuRepository)
        .create(() -> ObjectSkuMapper.INSTANCE.dtoToEntity(creator))
        .update(e -> e.init())
        .execute();
    String jsonStr = request.getJsonStr();
    //这里要注意对于简单的系统来讲存JSON也是可以的，存成结构化的数据是为了后面更好的进行数据迁移，商品中心会使用这些属性信息
    if(!StringUtils.isEmpty(jsonStr)){
      Map<String,Object> map = JSON.parseObject(jsonStr);
      List<SkuAttribute> skuAttributes = map.entrySet().stream().map(kv -> {
        Optional<TemplateItem> item = itemRepository.findByCode(kv.getKey());
        SkuAttribute skuAttribute = new SkuAttribute();
        skuAttribute.setValidStatus(ValidStatus.VALID);
        skuAttribute.setCode(kv.getKey());
        skuAttribute.setValue(Objects.nonNull(kv.getValue())?kv.getValue().toString():"");
        skuAttribute.setLabel(item.get().getName());
        skuAttribute.setItemId(item.get().getId());
        skuAttribute.setSkuId(objectSku.get().getId());
        return skuAttribute;
      }).collect(Collectors.toList());
      //批量存储属性值
      List<SkuAttribute> result = skuAttributeRepository.saveAll(skuAttributes);
      //批量存储关系
      List<SkuAttributeRel> relList = result.stream().map(sa -> {
        SkuAttributeRel sr = new SkuAttributeRel();
        sr.setSkuId(objectSku.get().getId());
        sr.setAttributeId(sa.getId());
        return sr;
      }).collect(Collectors.toList());
      skuAttributeRelRepository.saveAll(relList);
    }
    return objectSku.isPresent() ? objectSku.get().getId() : 0;
  }

