  /**
   * findByPage
   */
  @Override
  public Page<ObjectSkuVO> findByPage(PageRequestWrapper<ObjectSkuQuery> query) {
    BooleanBuilder booleanBuilder = new BooleanBuilder();
    Page<ObjectSku> page = objectSkuRepository.findAll(booleanBuilder,
        PageRequest.of(query.getPage() - 1, query.getPageSize(), Sort.by(
            Sort.Direction.DESC, "createdAt")));
    return new PageImpl<>(page.getContent().stream().map(entity -> new ObjectSkuVO(entity))
        .collect(Collectors.toList()), page.getPageable(), page.getTotalElements());
  }

  @Override
  public List<ObjectSkuVO> getSkusByCondition(String name) {
    BooleanBuilder bb = new BooleanBuilder();
    Optional.ofNullable(name)
        .ifPresent(n -> bb.and(QObjectSku.objectSku.skuName.like("%" + n + "%")));
    Iterable<ObjectSku> all = objectSkuRepository.findAll(bb);
    return Streams.stream(all).map(e -> new ObjectSkuVO(e))
        .collect(Collectors.toList());
  }
